<script lang="ts">
  // Options > Licenses: the third-party notices generated by scripts/gen-licenses.mjs
  // (`npm run licenses`) into public/licenses.json. A searchable list grouped by kind; a
  // row expands to the project's address and licence text (same as in Hyper and Farba).
  // Escape is handled by App's keydown handler.
  import { onMount, tick } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';

  interface Pkg {
    kind: 'bundled' | 'rust' | 'js';
    name: string;
    version: string;
    license: string;
    repository: string;
    note?: string;
    texts: string[];
  }
  interface Data {
    generated: string;
    packages: Pkg[];
    texts: Record<string, string>;
  }
  interface Props {
    t: Record<string, string>;
    onclose: () => void;
  }
  let { t, onclose }: Props = $props();

  let data = $state<Data | null>(null);
  let error = $state<string | null>(null);
  let query = $state('');
  let openKey = $state<string | null>(null);
  let closeBtn = $state<HTMLButtonElement | undefined>();

  const GROUPS: { kind: Pkg['kind']; label: string }[] = [
    { kind: 'bundled', label: 'licenses_bundled' },
    { kind: 'rust', label: 'licenses_rust' },
    { kind: 'js', label: 'licenses_js' },
  ];

  const filtered = $derived.by(() => {
    const q = query.trim().toLowerCase();
    const list = data?.packages ?? [];
    return q
      ? list.filter((p) => p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q))
      : list;
  });
  const summary = $derived.by(() => {
    const counts = new Map<string, number>();
    for (const p of data?.packages ?? []) counts.set(p.license, (counts.get(p.license) ?? 0) + 1);
    return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6);
  });

  onMount(() => {
    fetch('/licenses.json')
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((d: Data) => (data = d))
      .catch((e) => (error = String(e)));
    tick().then(() => closeBtn?.focus());
  });

  function openRepository(url: string) {
    invoke('plugin:opener|open_url', { url }).catch((e) => console.error('Open failed:', e));
  }

  const key = (p: Pkg) => `${p.kind}:${p.name}@${p.version}`;
</script>

<div class="lic-backdrop" role="presentation" onclick={(e) => e.target === e.currentTarget && onclose()}>
  <div class="lic-dialog" role="dialog" aria-modal="true" aria-labelledby="lic-title">
    <header>
      <div>
        <h2 id="lic-title">{t.licenses_title}</h2>
        <p class="dim">
          {t.licenses_intro}
          {#if data}· {data.packages.length} {t.licenses_components}{/if}
        </p>
      </div>
      <button bind:this={closeBtn} onclick={onclose}>{t.licenses_close}</button>
    </header>

    {#if data}
      <input type="search" placeholder={t.licenses_search} bind:value={query} />
      <div class="chips">
        {#each summary as [lic, n] (lic)}
          <button class="chip" class:on={query === lic} onclick={() => (query = query === lic ? '' : lic)}>{lic} · {n}</button>
        {/each}
      </div>
      <div class="list">
        {#each GROUPS as g (g.kind)}
          {@const items = filtered.filter((p) => p.kind === g.kind)}
          {#if items.length}
            <h3>{t[g.label]} <span class="dim">({items.length})</span></h3>
            {#each items as p (key(p))}
              {@const k = key(p)}
              <div class="item" class:open={openKey === k}>
                <button class="row" aria-expanded={openKey === k} onclick={() => (openKey = openKey === k ? null : k)}>
                  <span class="name">{p.name}{#if p.version}<span class="ver">{p.version}</span>{/if}</span>
                  <span class="lic" title={p.license}>{p.license}</span>
                </button>
                {#if openKey === k}
                  <div class="body">
                    {#if p.note}<p class="note">{p.note}</p>{/if}
                    <button class="link" onclick={() => openRepository(p.repository)}>{p.repository}</button>
                    {#each p.texts as id (id)}
                      <pre>{data.texts[id]}</pre>
                    {/each}
                  </div>
                {/if}
              </div>
            {/each}
          {/if}
        {/each}
      </div>
    {:else if error}
      <p class="dim">{error}</p>
    {:else}
      <p class="dim">…</p>
    {/if}
  </div>
</div>

